        <?php foreach ($payload['unpaid_documents'] as $document): ?><tr><td><?= pl_e(ucfirst($document['kind']) . ' / ' . $document['account_code']) ?></td><td><?= pl_e($document['party']) ?></td><td><?= pl_e($document['reference']) ?></td><td><?= pl_e($document['document_date']) ?></td><td><?= pl_e($document['due_date']) ?></td><td class="amount"><?= pl_e(pl_money($document['outstanding'])) ?></td></tr><?php endforeach; ?>
        </tbody></table></div><?php else: ?><p>No unpaid invoices or bills. Control balances are zero.</p><?php endif; ?>
