        <form method="post" action="<?= pl_e(pl_url('/opening-balances')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="confirm"><input type="hidden" name="preview_id" value="<?= (int) $preview['id'] ?>"><input type="hidden" name="payload_hash" value="<?= pl_e($preview['payload_hash']) ?>">
            <label class="checkbox"><input type="checkbox" name="confirmed" value="1" required> I checked the balanced totals against the source records and included all unpaid documents.</label><div class="form-actions"><button class="button primary" type="submit">Confirm opening balances</button><a class="button secondary" href="<?= pl_e(pl_url('/opening-balances')) ?>">Prepare a different preview</a></div>
