    <form class="panel" method="post" enctype="multipart/form-data" action="<?= pl_e(pl_url('/opening-balances')) ?>">
        <?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="action" value="preview"><input type="hidden" name="request_key" value="<?= pl_e(bin2hex(random_bytes(24))) ?>">
