        <?php foreach ($company['accounts'] as $account): if (!$account['is_active']) { continue; } ?><tr><th scope="row"><?= pl_e($account['code'] . ' · ' . $account['name']) ?></th><td><input class="opening-amount" aria-label="<?= pl_e($account['name'] . ' debit') ?>" name="debit_<?= (int) $account['id'] ?>" inputmode="decimal" value="<?= pl_e(pl_web_text($input, 'debit_' . $account['id'])) ?>"></td><td><input class="opening-amount" aria-label="<?= pl_e($account['name'] . ' credit') ?>" name="credit_<?= (int) $account['id'] ?>" inputmode="decimal" value="<?= pl_e(pl_web_text($input, 'credit_' . $account['id'])) ?>"></td></tr><?php endforeach; ?>
        </tbody></table></div>
        <details<?= pl_web_text($input, 'balances_csv') !== '' ? ' open' : '' ?>><summary>Import account balances from CSV instead</summary><p class="small muted">A supplied CSV replaces the fields above. Header: <code>account_code,debit,credit</code>. Use this book's exact account codes, up to 500 rows / 512 KiB.</p><label class="field">Balance CSV file<input type="file" name="balances_csv_file" accept=".csv,text/csv"></label><label class="field">Or paste balance CSV<textarea name="balances_csv" rows="5"><?= pl_e(pl_web_text($input, 'balances_csv')) ?></textarea></label></details>
