    <?php elseif (!$reviewing && $history === []): ?><div class="panel"><p><?= $company['setup_status'] === 'opening_required' ? 'An authorised owner can prepare and confirm these balances.' : 'This business does not need an opening cutover.' ?></p></div><?php endif; ?>
    <?php if ($history): ?><section class="panel"><h2>Cutover history</h2><div class="table-wrap"><table class="data-table"><caption class="sr-only">Confirmation and correction history</caption><thead><tr><th>Cutover</th><th>Status</th><th>Confirmed</th><th>Journal</th><th>Correction</th></tr></thead><tbody>
    <?php foreach ($history as $cutover): ?><tr><td>#<?= (int) $cutover['id'] ?> · <?= pl_e($cutover['cutover_date']) ?></td><td><?= pl_e(ucfirst($cutover['status'])) ?></td><td><time data-local-time datetime="<?= pl_e(str_replace(' ', 'T', $cutover['confirmed_at']) . 'Z') ?>"><?= pl_e($cutover['confirmed_at']) ?> UTC</time></td><td><?php if ($cutover['journal_id']): ?><a href="<?= pl_e(pl_url('/journals/detail', ['id' => $cutover['journal_id']])) ?>">View journal</a><?php else: ?>Zero opening<?php endif; ?></td><td><?php if ($cutover['reversed_journal_id']): ?><a href="<?= pl_e(pl_url('/journals/detail', ['id' => $cutover['reversed_journal_id']])) ?>">Linked reversal</a><?php endif; ?> <?= pl_e($cutover['reversal_reason'] ?? '') ?></td></tr><?php endforeach; ?>
    </tbody></table></div>
