    </section><?php endif; ?>
    <div class="form-actions"><a class="button secondary" href="<?= pl_e(pl_url('/periods')) ?>">Period administration</a><a class="button secondary" href="<?= pl_e(pl_url('/bank-reconciliation')) ?>">Bank reconciliation</a></div>
